import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 2

def design(feats):
    # Identify strong candidates using t-test and correlation
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('copy_number', 'expression', 'clinical'):
            t_stat = feats.x[:, i].T @ feats.y / np.sqrt(np.var(feats.x[:, i]) * np.sum(feats.y))
            if abs(t_stat) > 4.0:
                strong_candidates.append((fid, abs(t_stat)))

    # Sort by strength
    strong_candidates.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates
    filtered_candidates = []
    seen = set()
    for fid, _ in strong_candidates:
        if any(abs(np.corrcoef(feats.x[:, feats.column(fid)], feats.x[:, feats.column(other_fid)])[0,1]) > 0.6 
                for other_fid in seen):
            continue
        filtered_candidates.append(fid)
        seen.add(fid)
        if len(filtered_candidates) >= MAX_DRIVERS:
            break

    # If no strong candidates, return empty design
    if not filtered_candidates:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build regression components
    drivers = tuple(filtered_candidates[:MAX_DRIVERS])
    columns = tuple(filtered_candidates)

    # Add interaction terms for top 2 drivers
    products = []
    if len(drivers) >= 2:
        products = [(drivers[0], drivers[1])]

    # Weighted score: use standardized values of drivers
    loadings = {}
    for fid in drivers:
        loadings[fid] = 1.0

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

